package com.example.ml

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import java.io.BufferedReader
import java.io.InputStreamReader

/**
 * Numeric parity: the Kotlin port must reproduce PyTorch (model_best.pt) logits
 * on REAL clips within tolerance. Inputs + expected logits come from
 * tajweed_ml/dataset/parity_fixture.json (generated by src/generate_fixture.py
 * using train.py's own feature code + the CPU model).
 */
@RunWith(RobolectricTestRunner::class)
class TajweedNetParityTest {

    private fun loadResource(name: String): String {
        val stream = javaClass.classLoader.getResourceAsStream(name)
            ?: error("missing resource $name")
        return BufferedReader(InputStreamReader(stream)).use { it.readText() }
    }

    @Test
    fun parityWithPyTorchOnRealClips() {
        val weightsJson = JSONObject(loadResource("model_weights.json"))
        val net = TajweedNet(weightsJson)
        val fixture = JSONArray(loadResource("parity_fixture.json"))

        var maxErr = 0f
        var worst = ""
        for (i in 0 until fixture.length()) {
            val clip = fixture.getJSONObject(i)
            val lm = clip.getJSONArray("logmel")
            val T = lm.getJSONArray(0).length()
            val nMel = lm.length()
            val logmel = Array(nMel) { r -> FloatArray(T) { c -> lm.getJSONArray(r).getDouble(c).toFloat() } }
            val dur = clip.getDouble("dur").toFloat()
            val evArr = clip.getJSONArray("ev")
            val ev = FloatArray(evArr.length()) { evArr.getDouble(it).toFloat() }

            val logits = net.forward(logmel, dur, ev)
            val expected = clip.getJSONObject("expected_logits")
            for (rule in TajweedFeatures.metaRules()) {
                val got = logits[rule] ?: 0f
                val exp = expected.getDouble(rule).toFloat()
                val err = kotlin.math.abs(got - exp)
                if (err > maxErr) { maxErr = err; worst = "${clip.getString("rule")}/$rule got=$got exp=$exp" }
            }
        }
        println("[parity] max absolute logit error = $maxErr  ($worst)")
        assertTrue("Kotlin port diverges from PyTorch (maxErr=$maxErr). Worst: $worst",
            maxErr < 1e-2f)
    }
}
